import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth } from './helpers';

test.describe(`task creator: edit or delete my own task`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`a team member can only edit or delete tasks they created; attempts to modify other members' tasks are rejected`, async ({ browser }) => {
    // Two-actor test: node 0 creates a task; node 1 must NOT see edit/delete controls
    // for it because the UI only renders those buttons when task.creator === selfIdentity.
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();

    try {
      await loginViaHash(pageA, 0);
      await loginViaHash(pageB, 1);

      // Node 0 creates a task.
      await pageA.getByPlaceholder('Add a new task…').fill('Node-0 owned task');
      await pageA.getByRole('button', { name: '+ Add' }).click();
      await expect(pageA.getByText('Node-0 owned task')).toBeVisible({ timeout: 5_000 });

      // Node 0 can see its own Edit and Delete buttons.
      await expect(pageA.getByTitle('Edit task')).toBeVisible({ timeout: 5_000 });
      await expect(pageA.getByTitle('Delete task')).toBeVisible({ timeout: 5_000 });

      // Node 1 waits for the task to replicate, then checks that no edit/delete buttons exist.
      await expect(pageB.getByText('Node-0 owned task')).toBeVisible({ timeout: 5_000 });
      await expect(pageB.getByTitle('Edit task')).toBeHidden({ timeout: 2_000 });
      await expect(pageB.getByTitle('Delete task')).toBeHidden({ timeout: 2_000 });
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });
});
